// Generate unique coupon code for happy customers
const items = $input.all();

return items.map(item => {
  const appointmentId = item.json.appointmentId || 'STAR';
  const timestamp = Date.now();
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();

  // Create unique coupon code
  const couponCode = `STAR10-${appointmentId.slice(0,4).toUpperCase()}-${random}`;

  // Set expiry date to 90 days from now
  const expiryDate = new Date();
  expiryDate.setDate(expiryDate.getDate() + 90);

  return {
    json: {
      ...item.json,
      couponCode: couponCode,
      couponValue: 10,
      couponDiscount: '$10',
      expiryDate: expiryDate.toISOString().split('T')[0],
      expiryDateFormatted: expiryDate.toLocaleDateString('en-AU', { 
        day: 'numeric', 
        month: 'long', 
        year: 'numeric' 
      })
    }
  };
});

